from PIL import Image
def topedge(f):
    im=Image.open(f"/home/robot/captures/{f}").convert("L");px=im.load()
    prof=[sum(px[x,y] for x in range(304,338))/34 for y in range(195,240)]
    for i in range(1,len(prof)):
        a,b=prof[i-1],prof[i]
        if (a-100)*(b-100)<0 and b<a and abs(b-a)>15:
            return 195+i-1+(100-a)/(b-a)
ts=[topedge(f"side_{i:03d}.jpg") for i in range(12,17)]
print(ts, "mean=%.3f"%(sum(ts)/len(ts)))
# reference side_003 top=211.49 at F=1.17; high load F=44.73
t=sum(ts)/len(ts)
d=(t-211.49)*34.0/54.5
print("compression=%.3f mm  dF=%.2f  k=%.3f"%(d,44.73-1.17,(44.73-1.17)/d))
EOF"}

